{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Nintedanib, a large lipophilic kinase inhibitor with poor solubility, has an absolute oral bioavailability of approximately 5% in healthy volunteers, supporting low F for similarly large, poorly soluble heteroaromatic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Vinpocetine, a poorly water-soluble fused alkaloid with extensive first-pass metabolism, has human oral bioavailability as low as 7%, supporting low F for the query's large lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Roquinimex, which shares the N-methyl-N-phenyl amide motif, showed complete oral bioavailability in healthy volunteers, but its small size and higher solubility limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tropisetron has absolute oral bioavailability of 52-66% in humans, but as a small basic drug it is not a strong structural analogue for the large neutral query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "The closest structural analogue, LCS1269, is predicted to have >30% bioavailability based on HIA models, but this is a computational prediction rather than a measured oral F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low: the query is a large, highly lipophilic, poorly soluble polycyclic topoisomerase inhibitor; direct human low-bioavailability analogues (nintedanib, vinpocetine) with similar physicochemical liabilities outweigh high-bioavailability small-molecule analogues and uncertain computational predictions.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query or a close structural analogue.",
    "Highest-similarity evidence (LCS1269, becatecarin) is based on predicted HIA, not measured absolute F.",
    "Unknown effects of efflux transporters, first-pass metabolism, and formulation on query absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

